<?php ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TanzaniaTrip | Transport Network</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css" rel="stylesheet"><link rel="stylesheet" href="assets/css/tanzania.css"><style>.transport-hero{min-height:470px;background:linear-gradient(90deg,#031f16dd,#031f1644),url('https://images.unsplash.com/photo-1549317661-bd32c8ce0db2?auto=format&fit=crop&w=2200&q=88') center/cover;color:#fff;display:flex;align-items:center}.network{position:relative;background:#fff;border-radius:28px;padding:35px;box-shadow:0 18px 55px #063b2918}.line{height:5px;background:linear-gradient(90deg,#08734a,#d9ad4d);position:absolute;left:14%;right:14%;top:50%;border-radius:99px}.node{position:relative;z-index:2;background:#fff;border:4px solid #08734a;width:78px;height:78px;border-radius:50%;display:grid;place-items:center;margin:auto;font-size:1.5rem;color:#063b29}.node small{position:absolute;top:86px;width:140px;text-align:center;font-size:.75rem;font-weight:800}.request{background:#062d20;color:#fff;border-radius:26px;padding:28px}</style></head><body><nav class="navbar navbar-expand-lg navbar-dark sticky-top"><div class="container"><a class="navbar-brand brand" href="index.php"><span class="brand-mark">TZ</span>TanzaniaTrip</a><button class="navbar-toggler" data-bs-toggle="collapse" data-bs-target="#nav"><span class="navbar-toggler-icon"></span></button><div id="nav" class="collapse navbar-collapse"><div class="navbar-nav ms-auto"><a class="nav-link" href="index.php">Home</a><a class="nav-link" href="hotel.php">Hotels</a><a class="nav-link" href="tours.php">Tours</a><a class="nav-link active" href="transport.php">Transport</a><a class="nav-link" href="rooms.php">Spatial Studio</a></div></div></div></nav><header class="transport-hero"><div class="container"><div class="eyebrow">Tanzania mobility layer</div><h1 class="display-1 fw-bold mt-3">Arrival is part of<br><span style="color:#f0ce72">the journey.</span></h1><p class="lead" style="max-width:720px">Connect airport, bus stand, hotel and attraction transfers instead of treating transport as an afterthought.</p></div></header><main><section class="section"><div class="container"><div class="network"><div class="row align-items-center g-4 text-center"><div class="col"><div class="node"><i class="bi bi-bus-front"></i><small>Bus stand</small></div></div><div class="col"><div class="node"><i class="bi bi-building"></i><small>Hotel</small></div></div><div class="col"><div class="node"><i class="bi bi-binoculars"></i><small>Attraction</small></div></div><div class="col"><div class="node"><i class="bi bi-airplane"></i><small>Airport</small></div></div></div></div></div></section><section class="section pt-0"><div class="container"><div class="row g-4"><div class="col-lg-7"><div class="card-premium p-4"><div class="kicker">Transfer builder</div><h2 class="mt-2">Build a transfer request.</h2><div class="row g-3 mt-2"><div class="col-md-6"><label class="form-label fw-bold">From</label><select id="from" class="form-select"><option>Dodoma Bus Stand</option><option>Julius Nyerere Airport</option><option>Arusha Airport</option><option>Zanzibar Airport</option></select></div><div class="col-md-6"><label class="form-label fw-bold">To</label><select id="to" class="form-select"><option>Hotel</option><option>Tour attraction</option><option>Bus stand</option><option>Airport</option></select></div><div class="col-md-6"><label class="form-label fw-bold">Travellers</label><input id="p" class="form-control" type="number" min="1" value="2"></div><div class="col-md-6"><label class="form-label fw-bold">Vehicle</label><select id="vehicle" class="form-select"><option>Comfort car</option><option>Van</option><option>4×4 safari vehicle</option><option>Executive transfer</option></select></div></div><button class="btn btn-tz btn-lg mt-4" id="calc">Preview transfer</button></div></div><div class="col-lg-5"><div class="request h-100"><div class="eyebrow">Live-ready dispatch</div><h3 class="mt-3">Your transfer</h3><div id="preview" class="mt-4"><strong>Choose your route.</strong><p class="text-white-50">The production layer can connect driver assignment, vehicle status, ETA and guest notifications.</p></div></div></div></div></div></section></main><script>document.querySelector('#calc').onclick=()=>{let f=document.querySelector('#from').value,t=document.querySelector('#to').value,p=document.querySelector('#p').value,v=document.querySelector('#vehicle').value;document.querySelector('#preview').innerHTML='<div class="badge text-bg-success mb-3">REQUEST READY</div><h4>'+f+' → '+t+'</h4><p class="text-white-50 mb-1">'+p+' traveller'+(p==1?'':'s')+' · '+v+'</p><hr><p class="mb-0">Next layer: assign an available vehicle, calculate route time and attach this transfer to the hotel or tour itinerary.</p>'}</script></body></html>